import{_ as a,o as n,c as s,a0 as c}from"./chunks/framework.DCluYYrN.js";const _=JSON.parse('{"title":"x86_64 サポート","description":"","frontmatter":{},"headers":[],"relativePath":"ja_JP/guide/x86_64-support.md","filePath":"ja_JP/guide/x86_64-support.md"}'),l={name:"ja_JP/guide/x86_64-support.md"};function t(o,e,i,r,p,d){return n(),s("div",null,[...e[0]||(e[0]=[c(`<h1 id="x86-64-サポート" tabindex="-1">x86_64 サポート <a class="header-anchor" href="#x86-64-サポート" aria-label="Permalink to &quot;x86_64 サポート&quot;">​</a></h1><p>KernelSU は <code>x86_64</code> アーキテクチャを完全にサポートしています。ただし、upstream kernel の最近のセキュリティ変更により、最新の <code>x86_64</code> カーネルへ KernelSU を統合するには、統一された syscall dispatcher を正しく動作させるための追加対応が必要です。</p><h2 id="なぜ動かなくなったのですか" tabindex="-1">なぜ動かなくなったのですか？ <a class="header-anchor" href="#なぜ動かなくなったのですか" aria-label="Permalink to &quot;なぜ動かなくなったのですか？&quot;">​</a></h2><p>新しいカーネルバージョンでは、syscall table を強化するための <a href="https://git.kernel.org/pub/scm/linux/kernel/git/stable/linux.git/commit/?id=1e3ad78334a69b36e107232e337f9d693dcc9df2" target="_blank" rel="noreferrer">コミット</a> が導入されました。この変更により、システムコール経路内の間接分岐が一連の直接条件分岐へ変換されました。</p><p>KernelSU の <code>syscall_hook</code> は、フックしたシステムコールを統一 dispatcher にルーティングするために syscall table のエントリ変更へ依存しています。新しい hardening はシステムコール経路を変更するため、カーネルはそれらの syscall table 変更を無視します。KernelSU がこの制限を正しく処理しないまま syscall table を hook しようとすると、呼び出しを正しくルーティングできず、kernel panic を防ぐために初期化を中断します。</p><h2 id="どうすればよいですか" tabindex="-1">どうすればよいですか？ <a class="header-anchor" href="#どうすればよいですか" aria-label="Permalink to &quot;どうすればよいですか？&quot;">​</a></h2><p><code>x86_64</code> の syscall hook 問題には 2 つの公式サポートされた方法があります。</p><ol><li>カーネルのビルドオプション <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code> を有効にする。</li><li>従来どおりカーネルソースパッチ方式を使う。</li></ol><p>必要なのはどちらか一方だけです。両方を同時に適用しないでください。</p><h3 id="方法-1-ksu-x86-patch-syscall-dispatcher-を有効にする" tabindex="-1">方法 1: <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code> を有効にする <a class="header-anchor" href="#方法-1-ksu-x86-patch-syscall-dispatcher-を有効にする" aria-label="Permalink to &quot;方法 1: \`KSU_X86_PATCH_SYSCALL_DISPATCHER\` を有効にする&quot;">​</a></h3><p>KernelSU 3.3.0 では、<code>x86_64</code> 向けの新しい公式メカニズムとして <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code> ビルドオプションが追加されました。</p><p>このオプションを有効にすると、KernelSU は hardened syscall dispatcher を実行時に動的パッチし、従来のカーネルソースパッチを要求せずに syscall hook を動作させます。KernelSU 3.3.0 以降でカーネルをビルドする場合は、この方法を推奨します。</p><h3 id="方法-2-従来のカーネルソースパッチを適用する" tabindex="-1">方法 2: 従来のカーネルソースパッチを適用する <a class="header-anchor" href="#方法-2-従来のカーネルソースパッチを適用する" aria-label="Permalink to &quot;方法 2: 従来のカーネルソースパッチを適用する&quot;">​</a></h3><p><code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code> を有効にしたくない場合は、これまでのカーネルパッチ方式を継続して使えます。</p><p>これらの新しいカーネルで KernelSU を動作させるには、この syscall hardening を回避できるパッチを適用してください。</p><div class="danger custom-block"><p class="custom-block-title">セキュリティ警告</p><p>この 2 つの方法のいずれかを使うことは、speculative execution 脆弱性への対策を意図的に回避または弱めることを意味します。</p><p>これにより、system call に対する間接分岐の攻撃面が再び開かれます。<strong>本番サーバーや、厳格な side-channel セキュリティが重要なシステムでは、これら 2 つの方法のいずれも使わないでください。</strong> これらの方法は、特定のハードウェア脆弱性対策よりも KernelSU による root アクセスを優先するテスト環境向けです。</p></div><p>以下からカーネルバージョンに一致するパッチを選んで適用してください。これらのパッチは <code>X86_FEATURE_INDIRECT_SAFE</code> という機能を作成し、カーネルコマンドライン <code>syscall_hardening=off</code> で有効化できます。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>For kernel 6.6:</span></span>
<span class="line"><span>https://github.com/android-generic/kernel_common/commit/fe9a9b4c320577c30e1f22d04039e414c6a3cdec</span></span>
<span class="line"><span>https://github.com/android-generic/kernel_common/commit/df772e99e392f24b395ceaf7b26974e3e4828ee9</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For kernel 6.12:</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/dd2c602268fdc81f4d3b662f6a15142ac0ec7bcd</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/7d99237ae5da61c19447138da3282ae37d43857b</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For kernel 6.18:</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/40b1c323d1ad29c86e041d665c7f089b9a3ccfb5</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/f5813e10b7630e1ccd86fc2c4cf30eef60b64a82</span></span></code></pre></div><h2 id="どちらを選ぶべきですか" tabindex="-1">どちらを選ぶべきですか？ <a class="header-anchor" href="#どちらを選ぶべきですか" aria-label="Permalink to &quot;どちらを選ぶべきですか？&quot;">​</a></h2><ul><li>KernelSU 3.3.0 以降を使っていて、KernelSU のビルド設定を変更できるなら <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code> を有効にしてください。</li><li>現在のカーネルパッチ運用を維持したいなら、上記の従来のソースパッチを使い続けてください。</li></ul>`,20)])])}const u=a(l,[["render",t]]);export{_ as __pageData,u as default};
